import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.DdtnLau3.js";const b=JSON.parse('{"title":"Web 开发","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/web-development.md","filePath":"zh/guide/web-development.md"}'),o={name:"zh/guide/web-development.md"};function r(d,e,p,n,c,l){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="web-开发" tabindex="-1">Web 开发 <a class="header-anchor" href="#web-开发" aria-label="Permalink to &quot;Web 开发&quot;">​</a></h1><p>使用可复用的 <code>pphboy/piwork-web-base</code> 环境，在 Work 内开发 Web 应用。采用当前默认 Brain 的新应用使用 <strong>FastAPI + React + TypeScript + Vite</strong>；你也可以指定其他技术栈或派生自己的镜像。</p><p>Harness 在 Agent 容器中编辑 Work 共享工作空间，Core 以独立 Service 运行应用。基础镜像提供工具链、锁定的离线依赖和通用命令；应用源码与数据属于 Work。</p><h2 id="开发第一个应用" tabindex="-1">开发第一个应用 <a class="header-anchor" href="#开发第一个应用" aria-label="Permalink to &quot;开发第一个应用&quot;">​</a></h2><p>完成<a href="/piwork/zh/guide/quick-start.html">快速开始</a>后，在 CLI 容器中向已有 Work 发送任务：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">piwork-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> WORK_ID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --message</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;使用默认 Web base 开发任务看板，持久保存数据，部署为 Service，并验证实际运行的应用。&#39;</span></span></code></pre></div><p>将 <code>WORK_ID</code> 替换为实际 ID。默认部署 Skill 初始化可写应用、维护其 Spec，并通过已有 Service 工具部署和验证。已有应用目标会在任何覆盖写入前被拒绝；维护应用时读取并修改实际文件。</p><p>在 Desktop 的 Service 条目打开已声明的 Web 端口。自然语言任务启动开发，完成与否仍以实际 Service、Operation 和业务结果为准。</p><h2 id="修改后无需手动刷新" tabindex="-1">修改后无需手动刷新 <a class="header-anchor" href="#修改后无需手动刷新" aria-label="Permalink to &quot;修改后无需手动刷新&quot;">​</a></h2><p>继续让同一 Work 修改应用。交付包括必要的测试、检查、构建、Service 更新或重启，以及实际运行版本和受影响业务结果的验证。</p><p>标准模板在页面可见时每五秒检查就绪版本，并在恢复可见或连接时立即检查。页面自动采用新前端，恢复支持保存的非秘密草稿与当前路径；仅后端修改和普通 Agent Action 通过重读业务查询更新界面。显式开发模式支持 React Fast Refresh 与后端重载。</p><p>版本绑定对应源码、锁文件和实际镜像环境，因此仅升级基础环境也会让已打开页面采用新产物。失败构建、相同版本和断线不会造成循环刷新。该能力由模板提供；既有应用或第三方页面需要自己的更新支持。</p><p>应用版本读取不启动额外 Agent Run，也不 Apply 脑包。</p><h2 id="环境与运行方式" tabindex="-1">环境与运行方式 <a class="header-anchor" href="#环境与运行方式" aria-label="Permalink to &quot;环境与运行方式&quot;">​</a></h2><p>已发布基础镜像支持 <code>linux/amd64</code>，固定 Python 3.13.16、Node 24.21.0、FastAPI 0.143.0、React 19.3.0、TypeScript 7.0.2、Vite 8.3.4 和 sqlite3 CLI 3.40.1。完整依赖与校验以<a href="https://github.com/pphboy/piwork/tree/main/deploy/images/web-base" target="_blank" rel="noreferrer">上游环境和锁文件</a>为准。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker.io/pphboy/piwork-web-base:0.1.0-03395d0810f7-bbb24bdd0167-dirty@sha256:e83902fb568e97b2d01d488ce7c9c3d15f373ab58b46e041337baa832b8cfb81</span></span></code></pre></div><p>默认 Service 显式运行 <code>/usr/local/bin/piwork-web</code>，参数为 <code>[&quot;run&quot;, &quot;--app&quot;, &quot;/var/data/workspace/apps/&lt;service-name&gt;&quot;]</code>。FastAPI 通过单个声明的 HTTP <strong>8080</strong> 端口提供构建后的前端、API、应用交互接口和健康检查。Core 授予 workspace 访问并注入受管交互身份，单独启动容器不会取得该身份。</p><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>piwork-web prepare</code></td><td>从锁定离线缓存准备应用目录内的依赖。</td></tr><tr><td><code>piwork-web check</code></td><td>执行隔离的前后端测试和类型检查。</td></tr><tr><td><code>piwork-web build</code></td><td>发布匹配已检查源码与环境的前端产物。</td></tr><tr><td><code>piwork-web serve</code></td><td>提供已检查的应用。</td></tr><tr><td><code>piwork-web run</code></td><td>准备、检查、构建并运行。</td></tr><tr><td><code>piwork-web dev</code></td><td>显式运行前后端开发模式。</td></tr></tbody></table><p>这些命令在应用容器中执行，默认 Skill 选择相应 Service 命令并检查结果。标准依赖集合支持离线；新增依赖需要匹配的锁定制品或派生镜像。</p><h2 id="持久文件与-sqlite3" tabindex="-1">持久文件与 sqlite3 <a class="header-anchor" href="#持久文件与-sqlite3" aria-label="Permalink to &quot;持久文件与 sqlite3&quot;">​</a></h2><p>源码、锁文件、可写依赖和构建结果位于 <code>apps/&lt;service-name&gt;</code>，业务数据位于 <code>data/&lt;service-name&gt;</code>。Agent 和 Service 沿用共享文件身份，Service 根文件系统保持只读。重启或替换 Service 不重新初始化模板，也不清空业务数据。</p><p>已发布的 Agent 和 Web base 都提供真正的 sqlite3 命令。AI 的 bash 在 <strong>Agent</strong> 中运行，并遵守 Work 工具策略。工作站模板的授权只读检查可使用：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sqlite3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -readonly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/data/workspace/data/workstation/workstation.sqlite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;SELECT name FROM sqlite_master WHERE type=&quot;table&quot;;&#39;</span></span></code></pre></div><p>其他应用自行选择数据库名。普通业务修改仍遵守 Action/Query 契约，Core/history/Memory 等平台受管数据库不属于此应用操作路径。Core 和 CLI 宿主无需安装 Python、Node 或 sqlite3。</p><h2 id="资源政策与升级" tabindex="-1">资源政策与升级 <a class="header-anchor" href="#资源政策与升级" aria-label="Permalink to &quot;资源政策与升级&quot;">​</a></h2><p>应用 Service <strong>不设置 Piwork 内存上限，也不预留 Service 内存</strong>。CPU、服务/卷数量及 Agent/helper 内存政策继续有效，实际可用内存由宿主与外层环境决定。旧 Service <code>memoryBytes</code> 值仅保留兼容历史，零表示无限制。</p><p>按正常关闭、启动流程升级 Core，受管恢复会替换旧受限 Service 容器并保留 workspace。既有 Work 保持捕获的 Brain 和 Agent 镜像；采用新指导或 Agent 工具需要正常包更新、镜像选择和显式 Apply。Core 升级不覆盖管理员默认选择，也不转换已有应用。</p><h2 id="维护或扩展基础镜像" tabindex="-1">维护或扩展基础镜像 <a class="header-anchor" href="#维护或扩展基础镜像" aria-label="Permalink to &quot;维护或扩展基础镜像&quot;">​</a></h2><p>长期维护源是 <strong>Piwork 仓库的 <code>deploy/images/web-base/</code></strong>。DockerHub 保存发布制品；运行中的 Work 或脑包引用不是环境构建源。</p><table tabindex="0"><thead><tr><th>位置</th><th>职责</th></tr></thead><tbody><tr><td><code>deploy/images/web-base/</code></td><td>Dockerfile、环境、锁文件、工具和双语手册。</td></tr><tr><td><code>scripts/</code> 与 <code>Makefile</code></td><td>构建、验证和独立发布入口。</td></tr><tr><td><code>internal/coreassets/piwork-brain/</code></td><td>部署指导、模板和固定镜像引用。</td></tr><tr><td><code>dist/web-base/</code></td><td>被忽略的本地候选和验证产物。</td></tr></tbody></table><p>下游可用固定 tag 和 digest 执行 <code>FROM</code>，在镜像构建时安装锁定依赖，并以 <code>10001:10001</code> 运行。Work 本身不因此取得 Docker build 或 socket 权限。</p><p>具体命令、派生与发行维护见<a href="https://github.com/pphboy/piwork/blob/main/deploy/images/web-base/README.zh-CN.md" target="_blank" rel="noreferrer">基础镜像手册</a>，已验证范围见<a href="https://github.com/pphboy/piwork/blob/main/docs/web-base-acceptance.md" target="_blank" rel="noreferrer">验收记录</a>。</p>`,32)])])}const k=t(o,[["render",r]]);export{b as __pageData,k as default};
